import 'package:flutter/material.dart';import 'package:printing/printing.dart';import '../services/api_service.dart';
class MyReportsScreen extends StatefulWidget{const MyReportsScreen({super.key});@override State<MyReportsScreen> createState()=>_S();}class _S extends State<MyReportsScreen>{List<dynamic> rows=[];bool loading=true;@override void initState(){super.initState();ApiService().myReports().then((x){if(mounted)setState((){rows=x;loading=false;});});}Future<void> pdf(dynamic r)async{final b=await ApiService().pillarReportPdf(r['pillar_key']);await Printing.layoutPdf(onLayout:(_)=>b,name:'${r['pillar_name']}.pdf');}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Meus relatórios')),body:loading?const Center(child:CircularProgressIndicator()):rows.isEmpty?const Center(child:Text('Seus relatórios aparecerão aqui quando os pilares forem gerados.')):ListView(padding:const EdgeInsets.all(16),children:[for(final r in rows)Card(child:ListTile(leading:const Icon(Icons.picture_as_pdf),title:Text('${r['pillar_name']}'),subtitle:Text(r['ready']==true?'Pilar concluído':'Relatório em evolução'),trailing:IconButton(icon:const Icon(Icons.print),tooltip:'Abrir / salvar PDF',onPressed:()=>pdf(r))))]));}
